use serde_json::Value;
use thrust_editor_doc::vdom::unescape_html;

/// Differential fuzz of entity decoding against zeed-dom's `unescapeHTML` (target/spike-0006/entities-fuzz.json).
/// `oracle_`: the input is generated by the TypeScript oracle and git-ignored, so this runs only under the `oracle`
/// and `deep` nextest profiles, and fails when the input is missing rather than passing with nothing compared.
#[test]
fn oracle_entities_match_zeed_dom() {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/spike-0006/entities-fuzz.json"
    );
    let s = std::fs::read_to_string(p)
        .unwrap_or_else(|e| panic!("{p}: {e} (generate it with tools/spike-0006/gen-all.sh)"));
    let c: Value = serde_json::from_str(&s).unwrap();
    let (mut ok, mut n) = (0, 0);
    let mut fails = vec![];
    for r in c["rows"].as_array().unwrap() {
        let input = r["input"].as_str().unwrap();
        let want = r["expected"].as_str().unwrap();
        let got = unescape_html(input);
        n += 1;
        if got == want {
            ok += 1;
        } else if fails.len() < 15 {
            fails.push(format!("{input:?} -> got {got:?} want {want:?}"));
        }
    }
    eprintln!("entity decoding vs entities 5.0.0: {ok}/{n}");
    for f in &fails {
        eprintln!("  FAIL {f}");
    }
    assert!(n > 0, "{p} has no rows: nothing was compared");
    assert_eq!(ok, n);
}
